sys_variable_value.value:
(function execute(inputs, outputs) {

    var result = {
        success: false,
        message: '',
        student: {}
    };

    // Always use the currently logged-in ServiceNow user.
    // Do not accept a student user from the conversational layer.
    var studentUserId = gs.getUserID();

    // Validate authenticated session
    if (!studentUserId) {
        result.message = 'No authenticated user session found.';
        outputs.student_context = JSON.stringify(result);
        return;
    }

    // Find Student Profile linked to the logged-in ServiceNow user
    var student = new GlideRecord('x_snc_visaguardi_0_student_profile');

    student.addQuery('user', studentUserId);
    student.setLimit(1);
    student.query();

    // Student profile not found
    if (!student.next()) {
        result.message = 'No Student Profile found for the current logged-in user.';
        outputs.student_context = JSON.stringify(result);
        return;
    }

    // Student profile found
    result.success = true;
    result.message = 'Student profile found.';

    result.student = {
        sys_id: student.getUniqueValue(),
        student_id: student.getValue('student_id'),

        first_name: student.getValue('first_name'),
        last_name: student.getValue('last_name'),
        email: student.getValue('email'),

        nationality: student.getValue('nationality'),

        degree_program: student.getValue('degree_program'),
        degree_level: student.getValue('degree_level'),
        university_name: student.getValue('university_name'),

        current_semester: student.getValue('current_semester'),
        intake_year: student.getValue('intake_year'),

        current_visa_status: student.getValue('current_visa_status'),
        visa_type: student.getValue('visa_type'),
        visa_expiry_date: student.getValue('visa_expiry_date'),
        passport_expiry_date: student.getValue('passport_expiry_date')
    };

    // Structured Student Context output
    outputs.student_context = JSON.stringify(result);

    // Individual outputs
    outputs.student_id = result.student.student_id;
    outputs.current_semester = result.student.current_semester;
    outputs.visa_status = result.student.current_visa_status;
    outputs.visa_type = result.student.visa_type;
    outputs.visa_expiry_date = result.student.visa_expiry_date;
    outputs.passport_expiry_date = result.student.passport_expiry_date;

    // Plain-text prompt for Gemini
    outputs.prompt_text =
        'Student Name: ' + result.student.first_name + ' ' + result.student.last_name +
        '\nStudent ID: ' + result.student.student_id +
        '\nEmail: ' + result.student.email +
        '\nNationality: ' + result.student.nationality +
        '\nUniversity: ' + result.student.university_name +
        '\nDegree Program: ' + result.student.degree_program +
        '\nDegree Level: ' + result.student.degree_level +
        '\nCurrent Semester: ' + result.student.current_semester +
        '\nIntake Year: ' + result.student.intake_year +
        '\nCurrent Visa Status: ' + result.student.current_visa_status +
        '\nVisa Type: ' + result.student.visa_type +
        '\nVisa Expiry Date: ' + result.student.visa_expiry_date +
        '\nPassport Expiry Date: ' + result.student.passport_expiry_date;

})(inputs, outputs);

