sys_element_mapping.value:
{
  "contents": [
    {
      "parts": [
        {
          "text": "You are a university student visa assistant. Analyze this student profile and provide a concise visa risk assessment. Student ID:  {{step[037bd13c-d08e-4812-b984-aca14939465b].student_id}}Visa Status: {{step[037bd13c-d08e-4812-b984-aca14939465b].visa_status}}Visa Type: {{step[037bd13c-d08e-4812-b984-aca14939465b].visa_type}}Visa Expiry Date: {{step[037bd13c-d08e-4812-b984-aca14939465b].visa_expiry_date}}Passport Expiry Date: {{step[037bd13c-d08e-4812-b984-aca14939465b].passport_expiry_date}}                     Return: risk level, key concerns, and recommended actions."
        }
      ]
    }
  ]
}

sys_variable_value.value:
(function execute(inputs, outputs) {

    var result = {
        success: false,
        message: '',
        assessment: ''
    };

    if (!inputs.response_body) {
        result.message = 'REST response body is empty.';
        outputs.visa_risk_assessment = JSON.stringify(result);
        return;
    }

    try {
        var response = JSON.parse(inputs.response_body);

        // Gemini response structure:
        // candidates[0].content.parts[0].text
        var assessment =
            response.candidates &&
            response.candidates[0] &&
            response.candidates[0].content &&
            response.candidates[0].content.parts &&
            response.candidates[0].content.parts[0] &&
            response.candidates[0].content.parts[0].text;

        if (!assessment) {
            result.message = 'Could not find assessment text in Gemini response.';
            outputs.visa_risk_assessment = JSON.stringify(result);
            return;
        }

        result.success = true;
        result.message = 'Visa risk assessment generated successfully.';
        result.assessment = assessment;

        outputs.visa_risk_assessment = assessment;

    } catch (e) {

        result.message = 'Failed to parse Gemini response: ' + e.message;

        outputs.visa_risk_assessment = JSON.stringify(result);
    }

})(inputs, outputs);

